    auto copyL12L0AAtom = MakeCopy(CopyL12L0A{}, CopyL12L0ATraitDefault{});
    auto copyL12L0BAtom = MakeCopy(CopyL12L0B{}, CopyL12L0BTraitDefault{});
    auto copyL0C2GMAtom = MakeCopy(CopyL0C2GM{}, CopyL0C2GMTraitDefault{});
    auto mmadAtom = MakeMmad(MmadOperation{}, MmadTraitDefault{});

    constexpr uint32_t kLoop = K / baseK;
    constexpr uint32_t L1_Index = 0;
    constexpr uint32_t L0_Index = 1;
    constexpr uint32_t L0C_Index = 2;

    AscendC::Mutex::Lock<PIPE_M>(L0C_Index);
    // Move the current core's full A/B tiles from GM to L1 once.
    AscendC::Mutex::Lock<PIPE_MTE2>(L1_Index);
    Copy(copyGM2L1Atom, l1ATensor, globalA);
    Copy(copyGM2L1Atom, l1BTensor, globalB);
    AscendC::Mutex::Unlock<PIPE_MTE2>(L1_Index);
    AscendC::Mutex::Lock<PIPE_MTE1>(L1_Index);

    for (uint32_t kIter = 0; kIter < kLoop; ++kIter) {
        // Load one K tile from L1 to L0, then accumulate it into L0C.
        AscendC::Mutex::Lock<PIPE_MTE1>(L0_Index);
        Copy(copyL12L0AAtom, l0ATensor, l1ATensor.Slice(MakeCoord(0, kIter * baseK), MakeShape(baseM, baseK)));
        Copy(copyL12L0BAtom, l0BTensor, l1BTensor.Slice(MakeCoord(kIter * baseK, 0), MakeShape(baseK, baseN)));
        AscendC::Mutex::Unlock<PIPE_MTE1>(L0_Index);
        AscendC::Mutex::Lock<PIPE_M>(L0_Index);

        MmadParams para{baseM, baseN, baseK, 0, kIter == 0};
        Mmad(mmadAtom.with(para), l0CTensor, l0ATensor, l0BTensor);

        AscendC::Mutex::Unlock<PIPE_M>(L0_Index);
    }
    AscendC::Mutex::Unlock<PIPE_MTE1>(L1_Index);
    AscendC::Mutex::Unlock<PIPE_M>(L0C_Index);
    // Store the completed output tile from L0C back to GM.
    AscendC::Mutex::Lock<PIPE_FIX>(L0C_Index);
    Copy(copyL0C2GMAtom, globalC, l0CTensor);
    AscendC::Mutex::Unlock<PIPE_FIX>(L0C_Index);
    AscendC::PipeBarrier<PIPE_ALL>();
}

int32_t main(int32_t argc, char* argv[])
{
    // matmul参数
    constexpr uint32_t M = 512;
    constexpr uint32_t K = 512;
    constexpr uint32_t N = 1024;
    // 矩阵乘执行单元Tile参数
    constexpr uint32_t baseM = 128;
    constexpr uint32_t baseK = 64;
    constexpr uint32_t baseN = 256;

    size_t aFileSize = M * K * sizeof(half);
    size_t bFileSize = K * N * sizeof(half);
    size_t cFileSize = M * N * sizeof(half);
    uint32_t numBlocks = 16;

    aclInit(nullptr);
    int32_t deviceId = 0;
    aclrtSetDevice(deviceId);
    aclrtStream stream = nullptr;
    aclrtCreateStream(&stream);

    half* aHost;
    half* aDevice;
    aclrtMallocHost((void**)(&aHost), aFileSize);
    aclrtMalloc((void**)&aDevice, aFileSize, ACL_MEM_MALLOC_HUGE_FIRST);
    ReadFile("./input/x1_gm.bin", aFileSize, aHost, aFileSize);
    aclrtMemcpy(aDevice, aFileSize, aHost, aFileSize, ACL_MEMCPY_HOST_TO_DEVICE);

    half* bHost;
    half* bDevice;
    aclrtMallocHost((void**)(&bHost), bFileSize);
    aclrtMalloc((void**)&bDevice, bFileSize, ACL_MEM_MALLOC_HUGE_FIRST);
    ReadFile("./input/x2_gm.bin", bFileSize, bHost, bFileSize);
    aclrtMemcpy(bDevice, bFileSize, bHost, bFileSize, ACL_MEMCPY_HOST_TO_DEVICE);

    half* cHost;
    half* cDevice;
    aclrtMallocHost((void**)(&cHost), cFileSize);
    aclrtMalloc((void**)&cDevice, cFileSize, ACL_MEM_MALLOC_HUGE_FIRST);

    matmul_custom<M, K, N, baseM, baseM, baseK, baseN><<<numBlocks, 0, stream>>>(aDevice, bDevice, cDevice);
    aclrtSynchronizeStream(stream);

    aclrtMemcpy(cHost, cFileSize, cDevice, cFileSize, ACL_MEMCPY_DEVICE_TO_HOST);
    WriteFile("./output/output.bin", cHost, cFileSize);

    aclrtFree(aDevice);
    aclrtFreeHost(aHost);
    aclrtFree(bDevice);
    aclrtFreeHost(bHost);
    aclrtFree(cDevice);
    aclrtFreeHost(cHost);

    aclrtDestroyStream(stream);
    aclrtResetDevice(deviceId);
    aclFinalize();
    return 0;
}

