11	/* !
12	 * \file matmul_advanced_api.asc
13	 * \brief 使用Matmul高级API实现矩阵乘法，展示高阶矩阵乘接口的使用方法
14	 */
15	
16	#include "data_utils.h"
17	#include "kernel_tiling/kernel_tiling.h"
18	#include "tiling/platform/platform_ascendc.h"
19	#include "tiling/tiling_api.h"
20	#include "acl/acl.h"
21	#include "kernel_operator.h"
22	#define ASCENDC_CUBE_ONLY
23	#include "lib/matmul_intf.h"
24	
25	using namespace matmul;
26	
27	__global__ __cube__ void matmul_custom(
28	    __gm__ uint8_t* a, __gm__ uint8_t* b, __gm__ uint8_t* c, __gm__ uint8_t* workspace,
29	    AscendC::tiling::TCubeTiling tiling)
30	{
31	    AscendC::TPipe pipe;
32	
33	    AscendC::GlobalTensor<half> aGlobal;
34	    AscendC::GlobalTensor<half> bGlobal;
35	    AscendC::GlobalTensor<float> cGlobal;
36	    // A、B、C矩阵均按ND格式连续存放在GM中，SetGlobalBuffer的第二个参数是元素个数。
37	    // A矩阵形状为[M, Ka]，B矩阵形状为[Kb, N]，C矩阵形状为[M, N]。
38	    // GlobalTensor只描述GM上的地址和长度，真正的数据搬运、L1/L0C切分由Matmul高阶API结合tiling完成。
39	    aGlobal.SetGlobalBuffer(reinterpret_cast<__gm__ half*>(a), tiling.M * tiling.Ka);
40	    bGlobal.SetGlobalBuffer(reinterpret_cast<__gm__ half*>(b), tiling.Kb * tiling.N);
41	    cGlobal.SetGlobalBuffer(reinterpret_cast<__gm__ float*>(c), tiling.M * tiling.N);
42	
43	    // Matmul模板参数描述A/B/C矩阵在Kernel侧的位置、格式和数据类型：
44	    // - A、B、C都来自GM，格式均为ND；
45	    // - A/B为half，C为float；
46	    // - 这里的配置需要和Host侧SetAType、SetBType、SetCType保持一致。
47	    Matmul<
48	        MatmulType<AscendC::TPosition::GM, CubeFormat::ND, half>,
49	        MatmulType<AscendC::TPosition::GM, CubeFormat::ND, half>,
50	        MatmulType<AscendC::TPosition::GM, CubeFormat::ND, float>>
51	        mm;
52	    // 纯Cube场景下，ASCENDC_CUBE_ONLY会使Matmul对象在Cube侧初始化。
53	    // Matmul高阶API内部通过GetSysWorkSpacePtr获取系统workspace指针。
54	    REGIST_MATMUL_OBJ(&pipe, GetSysWorkSpacePtr(), mm, &tiling);
55	    // SetOrgShape设置原始完整矩阵形状，单位为元素。接口要求在SetTensorA、SetTensorB之前调用。
56	    mm.SetOrgShape(tiling.M, tiling.N, tiling.Ka, tiling.Kb);
57	    // SetTensorA/SetTensorB设置当前核参与计算的A、B矩阵起始地址，第二个参数false表示不转置。
58	    // SetTensorA接口要求A地址空间至少覆盖singleCoreM * Ka。本样例中GetTiling得到的tiling结果按M轴分2个核：
59	    // - A偏移 = blockIdx * singleCoreM * Ka，表示跳过前面核已经处理的A矩阵行；
60	    // - B不按M轴分核，两个核都需要完整B矩阵参与K轴累加，因此从bGlobal[0]开始读取。
61	    mm.SetTensorA(aGlobal[GetBlockIdx() * tiling.singleCoreM * tiling.Ka], false);
62	    mm.SetTensorB(bGlobal[0], false);
63	    // IterateAll一次计算当前核负责的singleCoreM * singleCoreN大小的C矩阵块。
64	    // 本样例输出C按[M, N]连续存放，当前核写回偏移为blockIdx * singleCoreM * N。
65	    mm.IterateAll(cGlobal[GetBlockIdx() * tiling.singleCoreM * tiling.N]);
66	    // End用于结束当前Matmul对象的使用并释放内部计算资源；后续如果还有其他Matmul对象，
67	    // 调用End可避免多个Matmul对象之间的资源冲突。
68	    mm.End();
69	}
70	
71	AscendC::tiling::TCubeTiling GenerateTiling(platform_ascendc::PlatformAscendC* ascendcPlatform)
72	{
73	    constexpr int32_t M = 512;
74	    constexpr int32_t N = 512;
75	    constexpr int32_t K = 128;
76	
77	    AscendC::tiling::TCubeTiling tilingData;
78	    matmul_tiling::MultiCoreMatmulTiling tilingApi(*ascendcPlatform);
79	
80	    // SetDim设置多核Matmul tiling计算时可使用的核数。
81	    // 纯Cube矩阵计算场景下，GetTiling会在该核数约束内生成实际使用核数usedCoreNum。
82	    // 本样例中配置可使用的核数为2。
83	    tilingApi.SetDim(2);
84	    // SetAType/SetBType/SetCType设置矩阵所在位置、数据格式和数据类型。
85	    // 这些信息需要和Kernel侧MatmulType模板参数、SetTensorA/SetTensorB的转置参数保持一致：
86	    // A/B/C都在GM，格式为ND；A/B为float16且不转置；C为float。
87	    tilingApi.SetAType(
88	        matmul_tiling::TPosition::GM, matmul_tiling::CubeFormat::ND, matmul_tiling::DataType::DT_FLOAT16, false);
89	    tilingApi.SetBType(
90	        matmul_tiling::TPosition::GM, matmul_tiling::CubeFormat::ND, matmul_tiling::DataType::DT_FLOAT16, false);
91	    tilingApi.SetCType(matmul_tiling::TPosition::GM, matmul_tiling::CubeFormat::ND, matmul_tiling::DataType::DT_FLOAT);
92	
93	    // SetOrgShape设置原始完整矩阵形状，SetShape设置本次实际参与Matmul计算的m/n/k。
94	    // 本样例计算完整矩阵乘，没有局部矩阵或脏数据列，因此两者都设置为M/N/K。
95	    tilingApi.SetOrgShape(M, N, K);
96	    tilingApi.SetShape(M, N, K);
97	    // 本样例只计算C=A*B，不带bias；设置为false后Kernel侧也不需要调用SetBias。
98	    tilingApi.EnableBias(false);
99	    // SetBufferSpace用于设置Matmul可使用的L1/L0C/UB空间大小，单位为字节。
100	    // 传入-1表示使用当前AI处理器对应buffer的默认大小，由tiling接口据此选择base块和搬运策略。
101	    tilingApi.SetBufferSpace(-1, -1, -1);
102	
103	    // GetTiling输出TCubeTiling，里面包含usedCoreNum、singleCoreM/N/K、baseM/N/K等信息。
104	    // 如果返回-1表示tiling计算失败，此时tiling结果不可继续使用。
105	    int64_t res = tilingApi.GetTiling(tilingData);
106	    if (res == -1) {
107	        std::cout << "gen tiling failed" << std::endl;
108	    }
109	    return tilingData;
110	}
111	
112	int32_t main(int32_t argc, char* argv[])
113	{
114	#if defined(ASCENDC_CPU_DEBUG) && (__NPU_ARCH__ == 2201)
115	    auto ascendcPlatform = platform_ascendc::PlatformAscendCManager::GetInstance("Ascend910B1");
116	#elif defined(ASCENDC_CPU_DEBUG) && (__NPU_ARCH__ == 3510)
117	    auto ascendcPlatform = platform_ascendc::PlatformAscendCManager::GetInstance("Ascend950PR_9589");
118	#else
119	    auto ascendcPlatform = platform_ascendc::PlatformAscendCManager::GetInstance();
120	#endif
121	    size_t aFileSize = 512 * 128 * sizeof(uint16_t);
122	    size_t bFileSize = 128 * 512 * sizeof(uint16_t);
123	    size_t cFileSize = 512 * 512 * sizeof(float);
124	    size_t userWorkspaceSize = 0;
125	    size_t systemWorkspaceSize = static_cast<size_t>(ascendcPlatform->GetLibApiWorkSpaceSize());
126	    // Matmul高阶API内部可能使用系统workspace，Host侧申请后作为Kernel参数传入。
127	    size_t workspaceSize = userWorkspaceSize + systemWorkspaceSize;
128	    auto tiling = GenerateTiling(ascendcPlatform);
129	    // 纯Cube场景下，Host侧启动核数与tiling实际使用核数保持一致。
130	    uint32_t numBlocks = tiling.usedCoreNum;
131	
132	    aclInit(nullptr);
133	    int32_t deviceId = 0;
134	    aclrtSetDevice(deviceId);
135	    aclrtStream stream = nullptr;
136	    aclrtCreateStream(&stream);
137	
138	    uint8_t* aHost;
139	    uint8_t* aDevice;
140	    aclrtMallocHost((void**)(&aHost), aFileSize);
141	    aclrtMalloc((void**)&aDevice, aFileSize, ACL_MEM_MALLOC_HUGE_FIRST);
142	    ReadFile("./input/x1_gm.bin", aFileSize, aHost, aFileSize);
143	    aclrtMemcpy(aDevice, aFileSize, aHost, aFileSize, ACL_MEMCPY_HOST_TO_DEVICE);
144	
145	    uint8_t* bHost;
146	    uint8_t* bDevice;
147	    aclrtMallocHost((void**)(&bHost), bFileSize);
148	    aclrtMalloc((void**)&bDevice, bFileSize, ACL_MEM_MALLOC_HUGE_FIRST);
149	    ReadFile("./input/x2_gm.bin", bFileSize, bHost, bFileSize);
150	    aclrtMemcpy(bDevice, bFileSize, bHost, bFileSize, ACL_MEMCPY_HOST_TO_DEVICE);
151	
152	    uint8_t* workspaceDevice;
153	    aclrtMalloc((void**)&workspaceDevice, workspaceSize, ACL_MEM_MALLOC_HUGE_FIRST);
154	
155	    uint8_t* cHost;
156	    uint8_t* cDevice;
157	    aclrtMallocHost((void**)(&cHost), cFileSize);
158	    aclrtMalloc((void**)&cDevice, cFileSize, ACL_MEM_MALLOC_HUGE_FIRST);
159	
160	    matmul_custom<<<numBlocks, 0, stream>>>(aDevice, bDevice, cDevice, workspaceDevice, tiling);
161	    aclrtSynchronizeStream(stream);
162	
163	    aclrtMemcpy(cHost, cFileSize, cDevice, cFileSize, ACL_MEMCPY_DEVICE_TO_HOST);
164	    WriteFile("./output/output.bin", cHost, cFileSize);
165	
166	    aclrtFree(aDevice);
167	    aclrtFreeHost(aHost);
168	    aclrtFree(bDevice);
169	    aclrtFreeHost(bHost);
170	    aclrtFree(workspaceDevice);
171	    aclrtFree(cDevice);
172	    aclrtFreeHost(cHost);
173	    aclrtDestroyStream(stream);
174	    aclrtResetDevice(deviceId);
175	    aclFinalize();
176	    return 0;
177	}
